import "forge-std/Test.sol";
import "../src/crypto_roulette.sol";

contract CryptoRouletteTest is Test {
    CryptoRoulette roulette;
    address player = address(0x1);
    uint256 constant BET_PRICE = 1 ether;

    function setUp() public {
        roulette = new CryptoRoulette();
        vm.deal(address(roulette), 10 ether); // Fund the contract
        vm.deal(player, 10 ether);
    }

    function testPredictableRandomNumber() public {
        // Record initial balances
        uint256 initialContractBalance = address(roulette).balance;
        uint256 initialPlayerBalance = player.balance;

        // Predict the secret number using the same method as the contract
        uint256 blockTimestamp = block.timestamp;
        bytes32 blockHash = blockhash(block.number - 1);
        uint8 predictedNumber = uint8(uint256(keccak256(abi.encodePacked(blockTimestamp, blockHash)))) % 10 + 1;

        // Play with the predicted number
        vm.prank(player);
        roulette.play{value: BET_PRICE}(predictedNumber);

        // Check if player's balance changed (either lost bet or won jackpot)
        assertTrue(
            player.balance != initialPlayerBalance,
            "Player balance should change after playing"
        );
    }

    function testMultiplePlaysToVerifyRandomness() public {
        // Play multiple times with the same predicted number
        uint256 blockTimestamp = block.timestamp;
        bytes32 blockHash = blockhash(block.number - 1);
        uint8 predictedNumber = uint8(uint256(keccak256(abi.encodePacked(blockTimestamp, blockHash)))) % 10 + 1;

        uint256 wins;
        uint256 plays = 5;

        for (uint256 i = 0; i < plays; i++) {
            uint256 balanceBefore = player.balance;
            vm.prank(player);
            roulette.play{value: BET_PRICE}(predictedNumber);

            if (player.balance > balanceBefore) {
                wins++;
            }

            // Mine new block to get new random number
            vm.roll(block.number + 1);
        }

        // If wins are significantly higher than expected (1/10 chance), randomness is predictable
        assertTrue(
            wins <= plays / 5, // Expect max 1 win statistically, allowing some margin
            "Winning rate is too high, indicating predictable randomness"
        );
    }
}
